import{_ as r,o as t,c as a,ai as i}from"./chunks/framework.CaiDwmc7.js";const k=JSON.parse('{"title":"简介","description":"","frontmatter":{"title":"简介"},"headers":[],"relativePath":"crops/wheat/index.md","filePath":"crops/wheat/index.md"}'),l={name:"crops/wheat/index.md"};function o(n,e,m,d,b,h){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="小麦" tabindex="-1">小麦 <a class="header-anchor" href="#小麦" aria-label="Permalink to “小麦”">​</a></h1><p><a href="https://baike.baidu.com/item/%E5%B0%8F%E9%BA%A6/10237" target="_blank" rel="noreferrer">小麦</a>（学名：Triticum aestivum）是禾本科小麦属的一种一年生或越年生的草本植物，花果期5-7月，是全球最重要的三大粮食作物之一（另外两种是水稻和玉米）。</p><h2 id="植物特征" tabindex="-1">植物特征 <a class="header-anchor" href="#植物特征" aria-label="Permalink to “植物特征”">​</a></h2><ul><li><p><strong>结构</strong>：由根、茎、叶、穗和种子（麦粒）组成。其茎秆直立，中空有节；穗状花序直立，通常带有芒（即麦穗上细长的针刺）。</p></li><li><p><strong>生长环境</strong>：小麦具有很强的适应性，但在温带地区生长最为理想。根据播种季节的不同，主要分为：</p><ul><li><strong><a href="https://baike.baidu.com/item/%E5%86%AC%E5%B0%8F%E9%BA%A6/508343?fromModule=lemma_inlink" target="_blank" rel="noreferrer">冬小麦</a></strong>：秋季播种，经过冬季休眠（春化作用），次年夏季收获。</li><li><strong><a href="https://baike.baidu.com/item/%E6%98%A5%E5%B0%8F%E9%BA%A6/508357?fromModule=lemma_inlink" target="_blank" rel="noreferrer">春小麦</a></strong>：春季播种，当年秋季收获。</li></ul></li></ul><h2 id="产地" tabindex="-1">产地 <a class="header-anchor" href="#产地" aria-label="Permalink to “产地”">​</a></h2><p>中国小麦分布地域广泛，地理气候环境多样，既能种植<a href="https://baike.baidu.com/item/%E5%86%AC%E5%B0%8F%E9%BA%A6/508343?fromModule=lemma_inlink" target="_blank" rel="noreferrer">冬小麦</a>又能种植<a href="https://baike.baidu.com/item/%E6%98%A5%E5%B0%8F%E9%BA%A6/508357?fromModule=lemma_inlink" target="_blank" rel="noreferrer">春小麦</a>。</p><p>小麦主产区主要种植冬小麦，种植面积依次为<a href="https://baike.baidu.com/item/%E6%B2%B3%E5%8D%97/132980?fromModule=lemma_inlink" target="_blank" rel="noreferrer">河南</a>、<a href="https://baike.baidu.com/item/%E5%B1%B1%E4%B8%9C/155740?fromModule=lemma_inlink" target="_blank" rel="noreferrer">山东</a>、<a href="https://baike.baidu.com/item/%E5%AE%89%E5%BE%BD/37014?fromModule=lemma_inlink" target="_blank" rel="noreferrer">安徽</a>、<a href="https://baike.baidu.com/item/%E6%B1%9F%E8%8B%8F/154268?fromModule=lemma_inlink" target="_blank" rel="noreferrer">江苏</a>、<a href="https://baike.baidu.com/item/%E6%B2%B3%E5%8C%97/65777?fromModule=lemma_inlink" target="_blank" rel="noreferrer">河北</a>、<a href="https://baike.baidu.com/item/%E5%9B%9B%E5%B7%9D/212569?fromModule=lemma_inlink" target="_blank" rel="noreferrer">四川</a>、<a href="https://baike.baidu.com/item/%E6%B9%96%E5%8C%97/173862?fromModule=lemma_inlink" target="_blank" rel="noreferrer">湖北</a>、<a href="https://baike.baidu.com/item/%E9%99%95%E8%A5%BF/193811?fromModule=lemma_inlink" target="_blank" rel="noreferrer">陕西</a>、<a href="https://baike.baidu.com/item/%E6%96%B0%E7%96%86/132263?fromModule=lemma_inlink" target="_blank" rel="noreferrer">新疆</a>、<a href="https://baike.baidu.com/item/%E5%B1%B1%E8%A5%BF/188460?fromModule=lemma_inlink" target="_blank" rel="noreferrer">山西</a>、<a href="https://baike.baidu.com/item/%E7%94%98%E8%82%83/226159?fromModule=lemma_inlink" target="_blank" rel="noreferrer">甘肃</a>等11个省（区），约占全国冬小麦总面积的95%左右。栽培春小麦的主要有<a href="https://baike.baidu.com/item/%E5%86%85%E8%92%99%E5%8F%A4/173741?fromModule=lemma_inlink" target="_blank" rel="noreferrer">内蒙古</a>、新疆、甘肃、<a href="https://baike.baidu.com/item/%E9%9D%92%E6%B5%B7/31638?fromModule=lemma_inlink" target="_blank" rel="noreferrer">青海</a>、<a href="https://baike.baidu.com/item/%E9%BB%91%E9%BE%99%E6%B1%9F/7351?fromModule=lemma_inlink" target="_blank" rel="noreferrer">黑龙江</a>、<a href="https://baike.baidu.com/item/%E5%AE%81%E5%A4%8F/15715?fromModule=lemma_inlink" target="_blank" rel="noreferrer">宁夏</a>、<a href="https://baike.baidu.com/item/%E5%A4%A9%E6%B4%A5/132308?fromModule=lemma_inlink" target="_blank" rel="noreferrer">天津</a>、河北、<a href="https://baike.baidu.com/item/%E8%A5%BF%E8%97%8F/130045?fromModule=lemma_inlink" target="_blank" rel="noreferrer">西藏</a>等省（区），以内蒙古面积最大，西藏单产最高，其次为新疆。</p><h2 id="产量" tabindex="-1">产量 <a class="header-anchor" href="#产量" aria-label="Permalink to “产量”">​</a></h2><p>近五年来，中国小麦生产在经历2023年面积扩张但单产受灾的波动后，成功转向以科技驱动的单产提升模式，连续两年稳产于1.4亿吨高位，生产效率达到历史顶峰。</p><table tabindex="0"><thead><tr><th>年份</th><th>播种面积（千公顷）</th><th>总产量（万吨）</th><th>单位面积产量（公斤/公顷）</th></tr></thead><tbody><tr><td>2025</td><td>23581.8</td><td>14007.2</td><td><strong>5939.8</strong></td></tr><tr><td>2024</td><td>23587.4</td><td><strong>14009.9</strong></td><td>5939.6</td></tr><tr><td>2023</td><td><strong>23627.2</strong></td><td>13659.0</td><td>5781.0</td></tr><tr><td>2022</td><td>23518.5</td><td>13772.3</td><td>5856.0</td></tr><tr><td>2021</td><td>23568.4</td><td>13694.6</td><td>5810.6</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>数据来源：<a href="https://www.stats.gov.cn/" target="_blank" rel="noreferrer">国家统计局</a></p></div>',11)])])}const s=r(l,[["render",o]]);export{k as __pageData,s as default};
